using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Matrix.SharpWeightedLin;

internal sealed class SharpWeightedLinGeneralityDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Matrix/SharpWeightedLin/Generality.";
    private static readonly LibraryNoteRef Sra = LibraryNoteRef.Create("D5/L/Divergence/sra2026linconj");
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Hermitian inertia and spectral compression", H("Hermitian inertia and spectral compression"), Blocks([
            Describe.Lean(DescribeId.Create("nonneg-index"),
                DeclarationHandle.Create(Prefix + "nonnegIndex"),
                H("Nonnegative inertia count"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("Count all eigenvalues at least zero, including multiplicities."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("nonpos-index"),
                DeclarationHandle.Create(Prefix + "nonposIndex"),
                H("Nonpositive inertia count"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("Count all eigenvalues at most zero, including multiplicities."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-update-inertia"),
                DeclarationHandle.Create(Prefix + "positive_update_inertia"),
                H("Positive update inertia identity"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("For every invertible finite complex Hermitian H, every rectangular J and every positive definite W, the nonnegative inertia of H + J W J-star equals the positive inertia of H plus the nonpositive inertia of W-inverse + J-star H-inverse J. The rectangular J need not be an isometry. The argument uses both Schur complements of the same Hermitian block matrix, following Sra Lemma 2.1."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finrank-le-nonpos-index"),
                DeclarationHandle.Create(Prefix + "finrank_le_nonposIndex"),
                H("Nonpositive subspace dimension bound"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("Every complex subspace on which the actual Hermitian quadratic form is nonpositive has dimension at most the nonpositive inertia count. The proof separates it from the range of the positive spectral part."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("rank-reduction-order"),
                DeclarationHandle.Create(Prefix + "rank_reduction_order"),
                H("Inverse congruence power bound"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("If E lies below X to the power one over two b, times Y to the power one over a, times the same X power, inverse congruence and the Loewner-Heinz inequality bound the a power of the congruenced E by Y. Here X is positive definite, Y is positive semidefinite, zero is less than a and a is at most one, and b is positive."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("reduced-projection-compression"),
                DeclarationHandle.Create(Prefix + "reduced_projection_compression"),
                H("Inverse support compression formula"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("For positive definite X and a positive semidefinite idempotent E of rank k, the inverse-power congruence of E admits isometric support coordinates J. The compression S of X to the power one over b is positive definite, and the a power of the congruenced projection equals J S to the power minus a J-star, for all positive a and b. The zero rank case is included."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("spectral-lower-projection"),
                DeclarationHandle.Create(Prefix + "spectral_lower_projection"),
                H("Prescribed rank spectral lower projection"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("If descending eigenvalue j of a finite positive semidefinite matrix is at least one, the first j plus one spectral vectors define a positive semidefinite idempotent E of rank j plus one below that matrix. Indices in Lean start at zero."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("one-le-eigenvalue-of-nonnegindex-sub-one"),
                DeclarationHandle.Create(Prefix + "one_le_eigenvalue_of_nonnegIndex_sub_one"),
                H("Inertia threshold gives an indexed spectral bound"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("If the nonnegative inertia of A minus the identity is at least j plus one, descending eigenvalue j of the Hermitian A is at least one. This uses the exact correspondence between the sorted spectrum and inertia counts, including zero eigenvalues."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("eigenvalues-zero-rpow"),
                DeclarationHandle.Create(Prefix + "eigenvalues_zero_rpow"),
                H("Ordered spectrum commutes with positive powers"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("For a finite positive semidefinite matrix and every nonnegative real exponent, each descending eigenvalue of its continuous functional calculus power is the corresponding descending eigenvalue raised to that exponent."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("eigenvalues-real-smul"),
                DeclarationHandle.Create(Prefix + "eigenvalues_real_smul"),
                H("Real scaling of the Hermitian spectrum"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("Multiplication by a nonnegative real scalar multiplies each canonical Hermitian eigenvalue by that scalar. The proof reuses the existing descending spectral scaling theorem."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("nonnegindex-real-smul"),
                DeclarationHandle.Create(Prefix + "nonnegIndex_real_smul"),
                H("Positive scaling preserves nonnegative inertia"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("Every strictly positive real scalar preserves the full nonnegative inertia count of a finite Hermitian matrix."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("nonnegindex-mono"),
                DeclarationHandle.Create(Prefix + "nonnegIndex_mono"),
                H("Matrix order increases nonnegative inertia"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Sra),
                Blocks(Paragraph(Text("For finite Hermitian matrices A and B with A below B in the Loewner order, the nonnegative inertia count of A is at most that of B."))), DescribeRole.Theorem)])));
}
